$tests=0;
function check(bool $ok,string $label):void{global $tests;++$tests;if(!$ok)throw new RuntimeException($label);echo "PASS $label\n";}
function denied(callable $fn,string $label):void{try{$fn();}catch(DomainException){check(true,$label);return;}throw new RuntimeException('Not denied: '.$label);}
function key32():string{return bin2hex(random_bytes(16));}
$db=\Kulturhus\Verein\Tests\MySqlFixture::connect(':memory:');Database::migrate($db);
$db->exec("INSERT INTO clubs VALUES('a','Synthetic A'),('b','Synthetic B'); INSERT INTO actors(id,club_id,role) VALUES('f','a','treasurer'),('other','b','treasurer'),('editor','a','editor')");
$f=new Finance($db,'f');$other=new Finance($db,'other');$bank=$f->createAccount('Test bank','offline','0','2026-01-01');$second=$f->createAccount('Test second','offline','0','2026-01-01');$cash=$f->createAccount('Test cash','cash','10','2026-01-01');
$txData=['account'=>$bank,'booked_on'=>'2026-08-01','direction'=>'income','amount'=>'100','description'=>'Synthetic combined payment','counterparty'=>'Synthetic donor'];
$entryData=['kind'=>'donation','description'=>'Synthetic donation','counterparty'=>'Synthetic donor','amount'=>'60','document_date'=>'2026-08-01','due_date'=>'2026-08-01','category'=>'donations'];
$key=key32();$tx=$f->createTransaction($txData,$key);$don=$f->createEntry($entryData,key32());$fee=$f->createEntry(array_replace($entryData,['kind'=>'contribution','amount'=>'40']),key32());
check($f->createTransaction($txData,$key)===$tx&&count($f->transactions())===1,'transaction submission idempotent');
denied(fn()=>$f->createTransaction(array_replace($txData,['amount'=>'101']),$key),'idempotency key rejects different transaction payload');
check($f->overview('2026-08-01','2026-08-31')['income']===10000&&$f->overview('2026-08-01','2026-08-31')['donations']===0,'unassigned incoming transaction is income but not yet donation');
denied(fn()=>$other->transactionDetail($tx),'transaction tenant isolation');denied(fn()=>$other->allocations($don),'allocation list tenant isolation');
denied(fn()=>(new Finance($db,'editor'))->createTransaction($txData,key32()),'editor cannot capture transaction');
$foreign=$other->createAccount('Foreign','offline','0','2026-01-01');$foreignTx=$other->createTransaction(array_replace($txData,['account'=>$foreign]),key32());
denied(fn()=>$f->allocate($foreignTx,1,$don,1,'10',key32()),'foreign transaction cannot match local donation');
$foreignEntry=$other->createEntry($entryData,key32());denied(fn()=>$f->allocate($tx,1,$foreignEntry,1,'10',key32()),'local transaction cannot match foreign donation');
foreach(['0','100.001','-1'] as $bad)denied(fn()=>$f->allocate($tx,1,$don,1,$bad,key32()),'reject invalid allocation amount '.$bad);
$allocKey=key32();$l=$f->allocate($tx,1,$don,1,'25',$allocKey);
check($f->entry($don)['payment_state']==='partial'&&$f->entry($don)['remaining_cents']===3500,'partial donation has exact remaining amount');
check($f->transactionDetail($tx)['remaining_cents']===7500,'transaction exposes unallocated remainder');
check($f->allocate($tx,1,$don,1,'25',$allocKey)===$l&&count($f->allocations($don))===1,'replayed allocation creates no duplicate despite old versions');
denied(fn()=>$f->allocate($tx,2,$don,2,'26',$allocKey),'idempotency key rejects changed allocation');
denied(fn()=>$f->allocate($tx,1,$don,2,'10',key32()),'stale transaction version denied');
denied(fn()=>$f->allocate($tx,2,$don,1,'10',key32()),'stale entry version denied');
denied(fn()=>$f->allocate($tx,2,$don,2,'35.01',key32()),'cannot overpay receipt');
denied(fn()=>$f->cancel($don,2),'cannot discard partly paid donation');
check($f->overview('2026-08-01','2026-08-31')['donations']===2500&&$f->overview('2026-08-01','2026-08-31')['income']===10000,'partial allocation classifies donation without double counting income');
$l2=$f->allocate($tx,2,$fee,1,'40',key32());$l3=$f->allocate($tx,3,$don,2,'35',key32());
check($f->entry($don)['payment_state']==='paid'&&$f->entry($fee)['payment_state']==='paid'&&$f->transactionDetail($tx)['remaining_cents']===0,'one transaction splits between donation and membership fee');
check($f->overview('2026-08-01','2026-08-31')['income']===10000&&$f->overview('2026-08-01','2026-08-31')['donations']===6000,'split transactions count once in cashflow');
$next=$f->createEntry(array_replace($entryData,['amount'=>'1']),key32());denied(fn()=>$f->allocate($tx,4,$next,1,'0.01',key32()),'cannot overallocate a transaction');
denied(fn()=>$f->reverse($fee,2,'2026-08-02','Bad split reversal'),'cannot reverse whole bank payment through one split receipt');
$before=$f->accounts();denied(fn()=>$other->releaseAllocation($l,4,3,'Wrong club'),'foreign allocation cannot be released');
denied(fn()=>$f->releaseAllocation($l,3,3,'Stale'),'release rejects stale version');
$f->releaseAllocation($l,4,3,'Synthetic correction');
check($f->accounts()===$before,'release never changes account balances');
check($f->entry($don)['remaining_cents']===2500&&$f->entry($don)['payment_state']==='partial','release reopens only relevant receipt amount');
check($f->transactionDetail($tx)['remaining_cents']===2500&&$f->overview('2026-08-01','2026-08-31')['donations']===3500,'release frees amount and updates donation classification');
check(count($f->allocations($don))===2&&count(array_filter($f->allocations($don),fn($r)=>$r['voided_at']!==null))===1,'released association retained with reason');
denied(fn()=>$f->releaseAllocation($l,5,4,'Again'),'double release rejected');denied(fn()=>$f->allocate($tx,5,$don,4,'25',$allocKey),'released idempotency key cannot silently reactivate association');
$tx2=$f->createTransaction(array_replace($txData,['account'=>$second,'amount'=>'25','booked_on'=>'2026-08-02']),key32());$f->allocate($tx2,1,$don,4,'25',key32());
check($f->entry($don)['payment_state']==='paid'&&count(array_filter($f->allocations($don),fn($r)=>!$r['voided_at']))===2,'donation can receive payments from multiple accounts');
check(count($f->entries(['account'=>$bank,'kind'=>'donation']))===1&&count($f->entries(['account'=>$second]))===1,'receipt account filter includes every contributing account');
$out=$f->createTransaction(array_replace($txData,['direction'=>'expense','amount'=>'10']),key32());
denied(fn()=>$f->allocate($out,1,$next,1,'1',key32()),'outgoing transaction cannot fund a donation');
$expense=$f->createEntry(array_replace($entryData,['kind'=>'expense','amount'=>'5']),key32());denied(fn()=>$f->allocate($tx,5,$expense,1,'5',key32()),'incoming transaction cannot fund expense');$f->allocate($out,1,$expense,1,'5',key32());
check($f->overview('2026-08-01','2026-08-31')['expense']===1000,'partial expense classification does not duplicate cash outflow');
$cancel=$f->createEntry($entryData,key32());$f->cancel($cancel,1);denied(fn()=>$f->allocate($tx,5,$cancel,2,'1',key32()),'cancelled receipt cannot receive allocation');
$cashTx=$f->createTransaction(array_replace($txData,['account'=>$cash,'amount'=>'3']),key32());$cashDon=$f->createEntry(array_replace($entryData,['amount'=>'3']),key32());$cashAlloc=$f->allocate($cashTx,1,$cashDon,1,'3',key32());$f->closeCashbook($cash,'2026-08-01','13');
denied(fn()=>$f->releaseAllocation($cashAlloc,2,2,'Closed cash'),'cash closure prevents reclassification of closed period');
denied(fn()=>$f->createTransaction(array_replace($txData,['account'=>$cash,'amount'=>'1']),key32()),'cash closure prevents raw backdated transactions');
denied(fn()=>$f->createTransaction(array_replace($txData,['account'=>$cash,'direction'=>'expense','amount'=>'14','booked_on'=>'2026-08-02']),key32()),'raw cash transaction cannot make cash negative');
$oldTx=$f->transactionDetail($tx);$oldEntry=$f->entry($next);
$db->exec("CREATE TRIGGER fail_matching_audit BEFORE INSERT ON audit_events FOR EACH ROW BEGIN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='audit failure'; END");
try{$f->allocate($tx,(int)$oldTx['version'],$next,1,'1',key32());throw new RuntimeException('Expected audit failure');}catch(PDOException){}
check($f->transactionDetail($tx)===$oldTx&&$f->entry($next)===$oldEntry&&count($f->allocations($next))===0,'audit failure rolls back allocation and both versions');$db->exec('DROP TRIGGER fail_matching_audit');
$single=$f->createEntry(array_replace($entryData,['amount'=>'2']),key32());$f->recordPayment($single,1,$bank,'2026-08-03');$singleTx=$f->allocations($single)[0]['transaction_id'];$f->reverse($single,2,'2026-08-04','Synthetic reversal');
denied(fn()=>$f->allocate($singleTx,3,$next,1,'1',key32()),'reversed transaction cannot be reused');
check(!in_array($singleTx,array_column($f->transactions(['available'=>true]),'id'),true),'candidate list excludes reversed transactions');
check(Finance::decimal(100000000000)==='1000000000.00','maximum amount formats without floating point');
$unassignedCash=$f->createTransaction(array_replace($txData,['account'=>$cash,'amount'=>'1','booked_on'=>'2026-08-02']),key32());
denied(fn()=>$f->closeCashbook($cash,'2026-08-02','14'),'cash cannot close while unassigned transactions would become locked');
$parts=$f->createEntry(array_replace($entryData,['amount'=>'2']),key32());$partsTx=$f->createTransaction(array_replace($txData,['amount'=>'2']),key32());$f->allocate($partsTx,1,$parts,1,'1',key32());$f->allocate($partsTx,2,$parts,2,'1',key32());
check($f->canReverseEntry($parts),'two partial associations of the same unshared transaction can be reversed together');$f->reverse($parts,3,'2026-08-05','Synthetic correction','',0,$f->reversalSource($parts)['counter_review']);
check($f->entry($parts)['payment_state']==='reversed','reversal retains all partial associations');
$exportEntry=$f->createEntry(array_replace($entryData,['kind'=>'expense','amount'=>'10']),key32());$f->allocate($out,2,$exportEntry,1,'1',key32());
$csv=$f->export(['status'=>'partial']);check(str_contains($csv,'Zugeordnet EUR')&&str_contains($csv,'Offen EUR')&&str_contains($csv,'partial'),'CSV exposes partial status and remaining amounts');

// Native migration must preserve all existing payment and allocation history.
$before=[];foreach(['finance_accounts','finance_entries','finance_transactions','finance_allocations','finance_reversals'] as $table)$before[$table]=\Kulturhus\Verein\Tests\MySqlFixture::rows($db,$table);
Database::migrate($db);Database::migrate($db);
foreach($before as $table=>$rows)check($rows===\Kulturhus\Verein\Tests\MySqlFixture::rows($db,$table),'native migration preserves '.$table);
check(\Kulturhus\Verein\Tests\MySqlFixture::foreignKeyErrors($db)===[],'migration foreign keys valid');
echo "$tests matching checks passed\n";
